const S = { type: 'string' }, N = { type: 'number' };
export const MCP_TOOLS: { name: string; description: string; inputSchema: any; handler: (a: any) => Promise<any>; raw?: boolean }[] = [
  { name: 'process_list', description: 'List connected target agent sessions', inputSchema: { type: 'object', properties: {} }, handler: async () => [...sessions.values()] },
  { name: 'backends', description: 'Injection-backend matrix: sessions by entry, host-side Frida Gadget cache + loader command, device-side backend pointers. Pass session to classify which injection paths are really loaded in that process (zygisk / xposed_module / frida_gadget / self_load).', inputSchema: { type: 'object', properties: { session: S } }, handler: async (a) => { const m = backendMatrix(); return a.session ? { ...m, sessionBackends: await classifySession(a.session) } : m; } },
  { name: 'dumps_list', description: 'List captured dump artifacts (dex/so/region)', inputSchema: { type: 'object', properties: {} }, handler: async () => [...dumps.values()] },
  { name: 'compat_probe', description: 'Self-assess agent env + injection footprint: tracer/seccomp/backends/exec/anon/rwx', inputSchema: { type: 'object', properties: { session: S } }, handler: (a) => agentCmd(a.session, 'compat_probe') },
{ name: 'jni_onload', description: 'List, hook, unhook, inspect or manually invoke JNI_OnLoad. hook/call work on an already-loaded module; watch arms a one-shot LOAD-TIME interception: the agent hooks the dlopen entry point and patches the JNI_OnLoad of that module as soon as it is mapped, before the VM calls it (skipOriginal+returnValue can then replace that load-time call). call is dangerous and requires confirm:true. Events are emitted as JNI_ONLOAD with phase=manual|load.', inputSchema: { type: 'object', properties: { session: S, action: { type: 'string', enum: ['list', 'hook', 'unhook', 'call', 'status', 'watch', 'unwatch'] }, module: S, confirm: { type: 'boolean' }, skipOriginal: { type: 'boolean' }, returnValue: N }, required: ['action'] }, handler: (a) => { if (a.action === 'call' && a.confirm !== true) return Promise.resolve({ ok: false, error: 'jni_onload call requires confirm:true' }); return agentCmd(a.session, 'jni_onload', { action: a.action, module: a.module ?? '', skipOriginal: a.skipOriginal ? 'true' : 'false', returnValue: String(a.returnValue ?? 0) }, 30_000); } },
{ name: 'jni_hook', description: 'Install, remove or inspect the global JNIEnv->RegisterNatives hook. Each registration emits a JNI_NATIVE capture event with class, method, signature and native function pointer.', inputSchema: { type: 'object', properties: { session: S, action: { type: 'string', enum: ['install', 'uninstall', 'status'] } }, required: ['action'] }, handler: (a) => agentCmd(a.session, 'jni_hook', { action: a.action }, 20_000) },
{ name: 'jni_env_hook', description: 'Install, remove or inspect table-slot hooks on individual JNIEnv function-table entries (FindClass / GetMethodID / GetStaticMethodID / NewStringUTF / GetStringUTFChars / GetFieldID / GetStaticFieldID / byte-array read+writeback including the primitive-array critical pair, plus every Call*Method / NewObject family in all three JNI forms - varargs, V and A - with resolved member label and rendered argument values, and since v4.55 every Get/Set<Type>Field accessor (instance + static, 9 types) so native field reads/writes are observable, and since v4.63 the string-copy/pin entries, the direct-buffer trio, the exception flow, GetJavaVM, the reference lifecycle, type introspection, monitors and weak globals, the whole array-region family (Get/Set<Type>ArrayRegion for Boolean/Char/Short/Int/Long/Float/Double) and the array-elements family (Get/Release<Type>ArrayElements for the same seven types, events carrying isCopy and the release mode copyback/commit/abort)). Patterns install or remove whole groups in one call: "*" or "all" = every slot, "Call*" = prefix, "*Field" = suffix (the whole field family), "*Field*" = contains (the field ID lookups AND the accessors - what jni_field_digest needs to resolve names). setValue (a number, single slot only) makes a Set<Type>Field hook REWRITE the write: the wrapper stores that value instead of the caller one and the event reports value=.. requested=..; object-typed fields cannot be overridden and a wildcard pattern with setValue is refused. Each captured call emits a JNI_ENV event up to a per-slot budget (then only hit/drop counters move); the hook swaps one JNIEnv table slot, so uninstall restores the original pointer and status reports the live slot value next to original.', inputSchema: { type: 'object', properties: { session: S, setValue: S, action: { type: 'string', enum: ['install', 'uninstall', 'status'] }, function: { type: 'string', description: 'Fixed entry by name - the families are the ID lookups, Call*/NewObject in all three JNI forms, Get/Set<Type>Field, the string copy/pin entries, the direct-buffer trio, the exception flow, GetJavaVM, the reference lifecycle, type introspection, monitors, weak globals, Get/Set<Type>ArrayRegion and Get/Release<Type>ArrayElements for Boolean/Char/Short/Int/Long/Float/Double (action:status lists every slot the deployed agent knows) - or a Call* family in any of the three JNI forms: CallObjectMethod[V|A], CallBooleanMethod[V|A], CallByteMethod[V|A], CallCharMethod[V|A], CallShortMethod[V|A], CallIntMethod[V|A], CallLongMethod[V|A], CallFloatMethod[V|A], CallDoubleMethod[V|A], CallVoidMethod[V|A], CallStaticObjectMethod[V|A], CallStaticBooleanMethod[V|A], CallStaticByteMethod[V|A], CallStaticCharMethod[V|A], CallStaticShortMethod[V|A], CallStaticIntMethod[V|A], CallStaticLongMethod[V|A], CallStaticFloatMethod[V|A], CallStaticDoubleMethod[V|A], CallStaticVoidMethod[V|A], NewObject[V|A]. Wildcards install/uninstall many slots at once: "*" or "all" (every entry), a prefix such as "CallIntMethod*" / "Call*", a suffix such as "*Field" / "*ArrayRegion" / "*ArrayElements", or a contains pattern such as "*Field*"; the reply reports applied/failed. Status reports per slot installed/active/hits/dropped/slotValue/original/last (so the most recent event of a slot survives a flooded capture ring), and for action:status the function field doubles as a FILTER over the same pattern language plus the keyword "installed" (only the slots that are hooked right now) - the reply then states total/matched/emitted/truncated, so a filtered or clipped listing can never be mistaken for the whole table. The agent rejects unknown names.' } }, required: ['action'] }, handler: (a) => agentCmd(a.session, 'jni_env_hook', { action: a.action, function: a.function ?? '', setValue: a.setValue ?? '' }, 20_000) },
{ name: 'javahook_probe', description: 'Probe the optional statically linked LSPlant Java-method hook backend: compile-time availability and one-time ART initialization status. It does not install a hook by itself.', inputSchema: { type: 'object', properties: { session: S } }, handler: (a) => agentCmd(a.session, 'javahook_probe', {}, 20_000) },
{ name: 'java_hook', description: 'Install, remove or inspect Java method hooks through the LSPlant backend. action:hookAll installs every method of one class in a single call and returns hookIds plus matched (how many methods matched) - hooking all overloads or a whole class no longer needs a hand-written loop. Filter semantics differ per action: for action:hook, params is the exact parameter-type list and an empty list means a no-arg method; for action:hookAll, an empty/omitted method or params means ANY (the "*" spelling is also accepted). matched is the size of the match set and never shrinks to the install count, so a batch cut short by limit (clamped to the 16-slot ceiling and echoed back as limit) or by per-method failures is visible: the response then carries partial:true, plus matchedCapped/hookIdsTruncated when the 64-member collection budget or the response buffer was hit. stack:true captures a bounded caller chain at the hit (Class#method:line, innermost first, hook plumbing filtered) and reports it as stack in every JAVA_HOOK event plus lastStack in status - the Java analogue of the native backtrace; off by default because it walks the stack on every hit. params is a comma-separated Java parameter-type list (empty means no-arg); the target class is loaded through the app ClassLoader (inherited members are resolved through the superclass chain and the signature reports the declaring class; method "<init>" hooks a constructor, whose callback sees the arguments and whose result must remain the new object, so skipOriginal/returnValue are rejected for constructors). Multiple hooks are supported (bounded, and status reports maxHooks next to the active count); status lists every hook with hit count, last argument, last return value and last error. Each callback also emits a JAVA_HOOK event into the bounded live-capture stream.', inputSchema: { type: 'object', properties: { session: S, action: { type: 'string', enum: ['hook', 'hookAll', 'unhook', 'status'] }, hookId: N, className: S, method: S, params: S, skipOriginal: { type: 'boolean' }, returnValue: S, argIndex: N, argValue: S, stack: { type: 'boolean' }, limit: N }, required: ['action'] }, handler: (a) => agentCmd(a.session, 'java_hook', { action: a.action === 'hookAll' ? 'hook_all' : a.action, limit: a.limit ?? 0, hookId: a.hookId ?? 0, className: a.className ?? '', method: a.method ?? '', params: a.params ?? '', skipOriginal: a.skipOriginal ? 'true' : 'false', returnValue: a.returnValue ?? '', argIndex: a.argIndex ?? -1, argValue: a.argValue ?? '', stack: a.stack ? 'true' : 'false' }, 30_000) },
{ name: 'java_enum', description: 'Enumerate a live Java class through reflection: modifiers, superclass, interfaces, constructors, overloaded methods and fields. Read-only and uses the app ClassLoader.', inputSchema: { type: 'object', properties: { session: S, className: S }, required: ['className'] }, handler: (a) => agentCmd(a.session, 'java_enum', { className: a.className }, 20_000) },
{ name: 'java_call', description: 'Invoke a live Java method through reflection. params is a comma-separated parameter-type list; args is a JSON array of string/number/boolean/null values; field names a static field holding the receiver for instance methods. Returns the original result or a fail-loud exception.', inputSchema: { type: 'object', properties: { session: S, className: S, method: S, params: S, field: S, args: { type: 'array' } }, required: ['className', 'method'] }, handler: (a) => agentCmd(a.session, 'java_call', { className: a.className, method: a.method, params: a.params ?? '', field: a.field ?? '', args: JSON.stringify(a.args ?? []) }, 20_000) },
{ name: 'native_hook', description: 'Install, remove or inspect native hooks. backtrace:true makes every event carry the caller chain captured AT THE HIT (x30 + the x29 walk inside the thread stack), which native_backtrace then symbolizes. mode=got needs module+symbol; mode=inline accepts module+symbol or addr; mode=sites (module+symbol) rewrites the B/BL call sites that reach the function instead of the function entry, so the prologue of the target stays byte-identical while the CALLER bytes change (use it when the target verifies the prologue of the function itself). scope picks where to look: module (default, the target module), all (every file-backed module except JIT memfds, app code first; status reports scanned bytes and truncated when the budget stops it), or one module name/basename; sites bounds how many call sites are patched, and status lists each site with its form (b or bl), module, original and current instruction. for mode=got/inline unhook is soft by default (the patch stays installed but inactive, safe to reactivate) and hard:true really restores the original bytes after a quiesce window; mode=sites always restores the rewritten call-site instructions (the patch belongs to the agent, so there is no Dobby state to keep) and, in the rare case where a thunk page had to stay mapped because a thread was still inside it, reports the kept page as sitesPageKept in the status response (the hook itself is already gone at that point). mode=vtable (module+symbol) patches DATA slots holding the function address (function-pointer tables such as C++ vtables, callback tables, and the module own GOT entries) instead of any code, so neither the function nor any call site changes - use it for indirect calls. By default only slots in read-only mappings are touched, because a writable word that merely equals the target is as likely to be a constant; pass slotsWritable:true to include writable slots. Patching a GOT slot also redirects direct calls in that module and changes what the symbol address resolves to there (the code itself is unchanged). For mode=got the status also carries the MECHANISM, not just counters: slot (the relocation slot that was rewritten - address/target/original are all the same pre-patch slot VALUE, so without this they name nothing), slotsPatched (1; the install refuses anything else), slotCurrent (the live value, so a patch that something else overwrote is visible), pageProtRestored with pagePermsBefore/Now (the write puts the RELRO protection back; a page left writable is a footprint the target can see), installedAtMs/firstHitMs, and verdict = "fired" | "installed-never-fired". That verdict is the point: ok:true with hits:0 used to mean either "installed and never fired" or "there was no traffic to observe", and the caller could not tell them apart. slots bounds how many are patched, scope works like for sites, and status lists each slot with its module, mapping permissions, kind (got|data), original and current value. throttleMs (ms, clamped to 0..60000, 0 = off) keeps a hot hook such as read/write/futex from flooding the capture ring: the agent still applies argIndex/returnValue/skipOriginal to EVERY hit, but emits at most one event per hook per window and counts the hits it did not emit. The next emitted event carries throttled (how many hits it stands for) and status carries throttleMs plus the running throttled total, so emitted events = hits - throttled and a thinned log never looks like a quiet target. Each callback emits a NATIVE_HOOK event with the x0-x8/x18 registers through the bounded live-capture stream.', inputSchema: { type: 'object', properties: { session: S, action: { type: 'string', enum: ['hook', 'unhook', 'status'] }, hookId: N, mode: { type: 'string', enum: ['got', 'inline', 'sites', 'vtable'] }, module: S, symbol: S, addr: S, skipOriginal: { type: 'boolean' }, returnValue: S, argIndex: N, argValue: S, confirm: { type: 'boolean' }, hard: { type: 'boolean' }, sites: N, scope: S, slotsWritable: { type: 'boolean' }, backtrace: { type: 'boolean' }, throttleMs: N }, required: ['action'] }, handler: async (a) => {
    if (a.mode === 'inline' && a.addr && a.confirm !== true) return { ok: false, error: 'native_hook inline addr requires confirm:true' };
    // v4.99: every raw-address hook mode goes through the shared guard, and the agent receives the
    // guard's normalized address - the agent parses bare digit strings as decimal/octal, so
    // forwarding the caller's text could patch a different address than the one that was checked.
    // action:unhook/status only use hookId; guarding them would let a stale addr block an unhook.
    let hookAddr = a.addr ? String(a.addr) : '';
    let hookSid = a.session;
    if (a.action === 'hook' && a.addr && (a.mode === 'inline' || a.mode === 'sites' || a.mode === 'vtable')) {
      const sid0 = pickSid(a.session);
      if (!sid0) throw new Error('no session');
      const guard = await assertCallableAddress(sid0, a.addr);
      if (!guard.ok) return { ok: false, error: guard.error };
      hookAddr = guard.addr;
      hookSid = sid0;                    // guard and install must talk to the same session
    }
    return agentCmd(hookSid, 'native_hook', { action: a.action, hookId: a.hookId ?? 0, mode: a.mode ?? '', module: a.module ?? '', symbol: a.symbol ?? '', addr: hookAddr, skipOriginal: a.skipOriginal ? 'true' : 'false', returnValue: a.returnValue ?? '', argIndex: a.argIndex ?? -1, argValue: a.argValue ?? '', hard: a.hard ? 'true' : 'false', sites: a.sites ?? 0, scope: a.scope ?? '', slotsWritable: a.slotsWritable ? 'true' : 'false', backtrace: a.backtrace ? 'true' : 'false', throttleMs: normalizeThrottleMs(a.throttleMs) }, 20_000);
  } },
{ name: 'syscall_digest', description: 'Turn watched syscall hits into an answer: groups the NATIVE_HOOK events of the hooks you pass by (syscall number, CALLER frame) with counts, time window and threads, picks the first caller frame outside libc (that is the code that issued the syscall, which is what fingerprint-collection hunting needs), decodes the argument registers through the pointers the syscall actually uses (openat/faccessat/newfstatat paths, memfd_create names, uname utsname fields, connect IPv4/IPv6, ioctl request, socket domain/type) into a per-group example plus a paths histogram - which files does this code probe - and compares the runtime x8 with the statically attributed number so a wrong attribution shows up as a mismatch instead of a mislabel. Argument decoding reads target memory, so it is bounded by decodeLimit (default 40 samples) and can be turned off with decode:false. Install the watch with syscall_watch (it sets backtrace:true) and pass its hookIds plus expected {hookId: nr}.. Counters are reported as hits/throttled/emitted: a throttled watch counts every hit (from the authoritative agent hook status), so a thinned log cannot read as a quiet target', inputSchema: { type: 'object', properties: { session: S, hookIds: { type: 'array', items: { type: 'number' } }, expected: { type: 'object' }, sinceMs: N, limit: N, maxGroups: N, decode: { type: 'boolean' }, decodeLimit: N } }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return syscallDigest(sid, { hookIds: a.hookIds, expected: a.expected, sinceMs: a.sinceMs, limit: a.limit, maxGroups: a.maxGroups, decode: a.decode, decodeLimit: a.decodeLimit }); } },
{ name: 'java_trace', description: 'Class-level Java tracing in three explicit phases. action:start hooks every matching method of a class (hook_all semantics: method/params are optional filters, "*"/empty = any) and returns hookIds + matched + a capture cursor, KEEPING the hooks installed. action:digest drains the agent capture ring and turns the JAVA_HOOK events of those hook ids into a digest: per-method counts, first/last timestamp, threads, last argument and return, error counts, a chronological timeline (newest window) and a caller histogram when the hooks were started with stack:true. action:stop unhooks exactly the given ids (id 0 means every Java hook in the agent and is refused). Pass the cursor from start as sinceCaptureId on digest to see only events newer than that point. The digest drains the agent ring through the shared drainSession path, so it never eats records that another consumer still needs; a failed drain is reported in drain.ok instead of silently returning an empty trace. Trigger the target or let natural traffic run between start and digest.', inputSchema: { type: 'object', properties: { session: S, action: { type: 'string', enum: ['start', 'digest', 'stop'] }, className: S, method: S, params: S, limit: N, stack: { type: 'boolean' }, hookIds: { type: 'array', items: { type: 'number' } }, sinceCaptureId: N, maxTimeline: N, maxMethods: N, maxCallers: N }, required: ['action'] }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); if (a.action === 'start') return javaTraceStart(sid, { className: String(a.className ?? ''), method: a.method, params: a.params, limit: a.limit, stack: a.stack === true }); if (a.action === 'digest') return javaTraceDigest(sid, { hookIds: a.hookIds, sinceCaptureId: a.sinceCaptureId, maxTimeline: a.maxTimeline, maxMethods: a.maxMethods, maxCallers: a.maxCallers }); if (a.action === 'stop') return javaTraceStop(sid, { hookIds: a.hookIds }); throw new Error('action must be start | digest | stop'); } },
{ name: 'native_hook_all', description: 'Batch native hooking by exported-symbol pattern: give a module and a prefix/contains/exact filter and it resolves every matching exported FUNCTION from the module dump (not a hand-typed address list), installs inline hooks on up to limit of them (clamped to the 16 concurrent native slots) and returns hookIds with matched vs installedCount so truncation is visible. The batch is sized from the agent slot budget (native_hook status reports slots.max/used/free/byMode): with 0 free slots the call fails loud instead of failing symbol by symbol, and a short budget truncates the batch with limitReason explaining it. Address hooks are powerful, so confirm:true is required. action:unhook takes hookIds and removes exactly those. Filters are deterministic (address order), exclude can drop noisy names, and backtrace/throttleMs/skipOriginal/returnValue/argIndex/argValue are passed through to each hook (throttleMs keeps a hot symbol from flooding the ring; the response echoes the effective window).', inputSchema: { type: 'object', properties: { session: S, action: { type: 'string', enum: ['hook', 'unhook'] }, module: S, prefix: S, contains: S, exact: S, exclude: { type: 'array', items: { type: 'string' } }, limit: N, backtrace: { type: 'boolean' }, throttleMs: N, skipOriginal: { type: 'boolean' }, returnValue: S, argIndex: N, argValue: S, hookIds: { type: 'array', items: { type: 'number' } }, confirm: { type: 'boolean' } }, required: ['action'] }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); if (a.action === 'unhook') return nativeUnhookAll(sid, a.hookIds); if (a.confirm !== true) return { ok: false, error: 'native_hook_all requires confirm:true (it installs inline hooks in the target)' }; return nativeHookAll(sid, { module: String(a.module ?? ''), prefix: a.prefix, contains: a.contains, exact: a.exact, exclude: a.exclude, limit: a.limit, backtrace: a.backtrace === true, throttleMs: a.throttleMs, skipOriginal: a.skipOriginal === true, returnValue: a.returnValue, argIndex: a.argIndex, argValue: a.argValue }); } },
{ name: 'syscall_trace', description: 'One-shot syscall tracing in three phases, with the static attribution threaded automatically: action:start runs syscall_watch (module + optional syscalls filter name/number) and returns hookIds plus the expected {hookId: nr} map built from the watch response, so a mis-attribution later shows up as a mismatch instead of being copied wrong. Trigger the target in between. action:digest drains the agent ring through the shared drain path and returns the syscall digest of those hooks (callers outside libc, counts, paths histogram, runtime-x8 vs attributed mismatches). action:stop unhooks exactly the ids it was given - there is deliberately no unhook-all. Sites whose number could not be attributed are reported in unattributed and their events carry the runtime x8 only. start forwards throttleMs (0 = off) to the watch, which caps how often each site reports an event.', inputSchema: { type: 'object', properties: { session: S, action: { type: 'string', enum: ['start', 'digest', 'stop'] }, module: S, syscalls: { anyOf: [ { type: 'array', items: { anyOf: [ { type: 'string' }, { type: 'number' } ] } }, { type: 'string' } ] }, limit: N, throttleMs: N, hookIds: { type: 'array', items: { type: 'number' } }, expected: { type: 'object' }, sinceMs: N, decode: { type: 'boolean' }, decodeLimit: N, maxGroups: N }, required: ['action'] }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); if (a.action === 'start') return syscallTraceStart(sid, { module: String(a.module ?? ''), syscalls: a.syscalls, limit: a.limit, throttleMs: a.throttleMs }); if (a.action === 'digest') return syscallTraceDigest(sid, { hookIds: a.hookIds, expected: a.expected, sinceMs: a.sinceMs, decode: a.decode, decodeLimit: a.decodeLimit, maxGroups: a.maxGroups }); if (a.action === 'stop') return syscallTraceStop(sid, { hookIds: a.hookIds }); throw new Error('action must be start | digest | stop'); } },
{ name: 'trace_digest', description: 'Run a QBDI instruction trace of one native function and hand back a DIGEST instead of thousands of raw instructions: loops (header, body size, iterations), call targets with counts (symbolized when the module dump allows it), memory access shapes, materialised constants with known crypto magics flagged, branch shape and the hottest instructions. The raw stream stays available through qbdi_trace; use this one when the question is what the function DOES rather than what the exact instruction order was.. The reply carries seen/truncated/cap: a clipped trace (agent cap or reply-buffer limit) is flagged, and the digest describes the recorded prefix only', inputSchema: { type: 'object', properties: { session: S, symLib: S, symbol: S, args: { type: 'array' } }, required: ['session', 'symLib', 'symbol'] }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return traceDigest(sid, { symLib: a.symLib, symbol: String(a.symbol ?? ''), args: a.args }); } },
{ name: 'native_backtrace', description: 'Caller backtrace at a native hook hit (the native analogue of Thread.backtrace). With hookId it uses the newest event of that hook: when the hook was installed with backtrace:true the agent captured the chain AT THE HIT (x30 plus the x29 walk inside the thread stack), which is the trustworthy form - reading the stack later finds memory the process has already reused. Each frame is resolved to module + offset + the nearest dynamic symbol (exact when the symbol size covers the address). Explicit fp/lr instead performs a live x29 walk, which is best effort and reports its stopReason (unreadable stack, pointer outside a writable mapping, not ascending, loop) rather than inventing frames. A library mapped straight out of an APK is reported with symbolSource=archive-mapped because no standalone ELF image exists to symbolize against.', inputSchema: { type: 'object', properties: { session: S, hookId: N, fp: S, lr: S, maxFrames: N } }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return nativeBacktrace({ session: sid, hookId: a.hookId, fp: a.fp, lr: a.lr, maxFrames: a.maxFrames }); } },
  { name: 'native_call', description: 'Actively call a native function by module+symbol or absolute addr. A raw addr is first checked against the live maps (mapped AND executable) so a stale address - unloaded module, typo - fails on the host instead of jumping into unmapped memory inside the target; module+symbol re-resolves the maps on every call for the same reason. AAPCS64: integer/pointer args go to x0-x7 (up to 8), typed f:<float> / d:<double> args go to the FP bank (up to 8; the i-th FP argument uses d_i, and a float only fills its low 32 bits, i.e. s_i). Malformed input is rejected rather than guessed: unknown type prefix, empty argument, out-of-range number, more than 8 args per bank, or an args string over 279 bytes. The integer return is result/resultDecimal (x0); when FP args are used the d0 return is reported as fpResult/fpResultDouble/fpResultFloat with returnBank:"d0" and x0MayBeStale:true - a float return is the low 32 bits of d0, and x0 is only the answer if the target returns an int. This is an arbitrary target call and requires confirm:true; it can crash the target, so use only on authorized targets.', inputSchema: { type: 'object', properties: { session: S, module: S, symbol: S, addr: S, args: { type: 'array' }, confirm: { type: 'boolean' } } }, handler: async (a) => {
    if (a.confirm !== true) return { ok: false, error: 'native_call requires confirm:true (arbitrary target call can crash the process)' };
    const sid = pickSid(a.session);
    if (!sid) throw new Error('no session');
    // v4.94/v4.97: a raw address is checked against the live maps before anything is called - the
    // shared guard keeps this tool and the REST route from drifting apart.
    const guard = await assertCallableAddress(sid, a.addr);
    if (!guard.ok) return { ok: false, error: guard.error };
    return agentCmd(sid, 'native_call', { module: a.module ?? '', symbol: a.symbol ?? '', addr: guard.addr, args: (a.args ?? []).map((v: any) => String(v)).join(',') }, 20_000);
  } },
{ name: 'stealth', description: 'Opt-in anti-detection for this session: with action:"on" the allocations the inline-hook backend makes while it is inside a Dobby call (typically its trampoline arena) stop being anonymous executable pages and land in a memfd-backed mapping named like the ART JIT cache, so a target that scans its own /proc/self/maps for an executable mapping without a path no longer sees the hook pool. It changes what the target process looks like (authorized use only) and requires confirm:true for on/off; status reports enabled/installed/active, the live GOT slot value next to the original mmap, how many allocations were redirected, and the memfd error when the platform refuses (then the real mmap is used and nothing is hidden). Default off; pools created by earlier hooks are not moved.', inputSchema: { type: 'object', properties: { session: S, action: { type: 'string', enum: ['on', 'off', 'status'] }, confirm: { type: 'boolean' } }, required: ['action'] }, handler: (a) => { const act = String(a.action ?? ''); if (act !== 'status' && a.confirm !== true) return Promise.resolve({ ok: false, error: 'stealth on/off requires confirm:true (it changes the target process footprint; authorized use only)' }); return agentCmd(a.session, 'stealth', { action: act }, 15_000); } },
{ name: 'syscall_watch', description: 'Scan one loaded module for direct svc #0 sites (libc.so is the interesting one: its stubs are what ordinary app code reaches the kernel through), attribute each site to a syscall number by decoding the MOV that precedes the svc, inline-hook up to limit of the matching sites, and report hooks whose NATIVE_HOOK events carry x8 as the runtime syscall number. syscalls filters by name or number and accepts a CSV or an array ("uname,openat,117"); a filter that matches nothing fails loud. throttleMs (0 = off) caps how often each site reports an event - hot syscalls such as read/write/futex otherwise overflow the ring and make the digest look quiet; the response echoes the effective window. Host-side orchestration: dump + static scan + native_hook; agent remains execution-only.', inputSchema: { type: 'object', properties: { session: S, module: S, limit: N, throttleMs: N, syscalls: { anyOf: [ { type: 'array', items: { anyOf: [ { type: 'string' }, { type: 'number' } ] } }, { type: 'string' } ] } }, required: ['module'] }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return watchSyscalls(sid, { module: a.module, limit: a.limit, syscalls: a.syscalls, throttleMs: a.throttleMs }); } },
{ name: 'got_enum', description: 'Enumerate relocation/GOT entries for one loaded module: slot address, symbol name, current resolved value and relocation type. Optional filter matches one symbol exactly.', inputSchema: { type: 'object', properties: { session: S, module: S, filter: S }, required: ['module'] }, handler: (a) => agentCmd(a.session, 'got_enum', { module: a.module, filter: a.filter ?? '' }, 20_000) },
  { name: 'memory_maps', description: 'On-demand full /proc/self/maps of the target', inputSchema: { type: 'object', properties: { session: S } }, handler: (a) => agentCmd(a.session, 'maps') },
  { name: 'mem_backend', description: 'Force which route the agent reads target memory by, for the whole session: auto (default) lets it use /proc/self/mem when the target allows that fd and fall back to an in-process direct read otherwise; direct forces the fallback everywhere. The reply states requested vs effective backend, whether it is forced, and the errno of the last /proc/self/mem open attempt. This exists because a target that refuses that fd cannot be produced on demand, so without forcing it the fallback is only ever exercised on the single read command that has a per-call override - search, magic-scan, dump and art_dexfiles would never run on it. Set it back to auto when done: it is a diagnostic, not a mode to leave on.', inputSchema: { type: 'object', properties: { session: S, backend: { type: 'string', enum: ['auto', 'direct', 'proc'] } }, required: ['backend'] }, handler: (a) => agentCmd(a.session, 'mem_backend', { backend: a.backend }) },
  { name: 'memory_read', description: 'Read target memory at hex addr for size bytes (base64 out). The reply carries requested/short, so a truncated read is visible without recomputing it from the base64 length, and via names the route that answered. via:"direct" forces the direct in-process reader for this one read instead of /proc/self/mem - use it to cross-check a target that answers /proc/self/mem with plausible garbage, or to read when the target refuses that fd (a protector that calls prctl(PR_SET_DUMPABLE,0) makes open("/proc/self/mem") fail with EACCES even for the process itself, and the read then falls back to the direct route on its own)', inputSchema: { type: 'object', properties: { session: S, addr: S, size: N, via: { type: 'string', enum: ['auto', 'direct'] } }, required: ['addr', 'size'] }, handler: (a) => agentCmd(a.session, 'read', { addr: a.addr, size: a.size, ...(a.via === 'direct' ? { via: 'direct' } : {}) }) },
  { name: 'memory_disasm', description: 'Disassemble live target memory with host-side Capstone 5 (WASM). addr is an absolute hex address, or pass module plus offset to resolve the module base from live maps. size is bounded to 64 KiB and aligned to AArch64 instructions.', inputSchema: { type: 'object', properties: { session: S, addr: S, size: N, module: S, offset: S } }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return liveDisasm(sid, { addr: a.addr, size: a.size, module: a.module, offset: a.offset }); } },
  { name: 'memory_search', description: 'Search target memory for hex or text pattern. minAddr/maxAddr bound the scan to [lo, hi) in hex (0 or omitted = unbounded): regions outside are skipped rather than clipped, so the internal scan budget is spent on the range you asked about instead of whatever comes first in address order - on a large app the budget is otherwise exhausted by framework mappings before the scan reaches the app heap. The reply echoes the applied window, and regionClipped says whether a region inside it was still clipped.', inputSchema: { type: 'object', properties: { session: S, hex: S, text: S, limit: N, minAddr: S, maxAddr: S } }, handler: (a) => agentCmd(a.session, 'search', { pat: a.hex ?? Buffer.from(String(a.text ?? ''), 'utf8').toString('hex'), limit: a.limit ?? 256, minAddr: a.minAddr ?? '', maxAddr: a.maxAddr ?? '' }, 90_000) },
  { name: 'memory_scan_magic', description: 'Scan target memory for dex/elf/oat/vdex/zip magics. minAddr/maxAddr bound the scan to [lo, hi) in hex (0 or omitted = unbounded) - see memory_search for why aiming matters on a large app. The reply echoes the applied window, and truncated/regionClipped say whether the hit cap, the total cap or the per-region cap stopped it early, so a short list is never mistaken for a complete one.', inputSchema: { type: 'object', properties: { session: S, minAddr: S, maxAddr: S } }, handler: (a) => agentCmd(a.session, 'scan_magic', { minAddr: a.minAddr ?? '', maxAddr: a.maxAddr ?? '' }, 90_000) },
  { name: 'art_dexfiles', description: 'Enumerate loaded DexFiles via ART ClassLoader structures (no magic scan)', inputSchema: { type: 'object', properties: { session: S } }, handler: (a) => agentCmd(a.session, 'art_dexfiles', {}, 30_000) },
  { name: 'capture_start', description: 'Install the PERSISTENT hook set in this target and stream what it catches into the live store (read it with live_captures / crypto_identify / flow_correlate). This is the target-agnostic path that replaced the one-shot crypto_capture / net_capture / file_capture / detect_watch probes: the agent hardcodes neither a module nor a trigger method, so YOU name the modules here and provoke the workload with java_call {className, method, params, args}. Modules: cryptoModule (empty = scan every file-backed module and hook each one holding an EVP/SSL pointer), fileModule (empty = no file hooks), sysModule (empty = no ptrace/access/sysprop hooks). ok is a VERDICT, not the agent\'s unconditional ok:true. It re-arms from a clean slate (drain -> stop -> start) because the agent matches a GOT slot by VALUE: an install running while our own wrapper already sits in the slot reports 0 for it, which is indistinguishable from "not imported" (measured: a repeat call said 14/27, a clean re-arm said 23/27). installed is how many symbols came out live, attempted is how many the agent reported for the module set you asked for, and notInstalled names the ones that are genuinely absent from that module. With cryptoModule empty a symbol that installed nowhere is a real failure (ok:false, fail-loud); with a named module a missing symbol is normal (partial:true) because that module may not import it. complete:false whenever the answer is not fully trustworthy. Hooks stay live until capture_stop.', inputSchema: { type: 'object', properties: { session: S, cryptoModule: S, fileModule: S, sysModule: S } }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return setCapture(sid, true, { cryptoModule: a.cryptoModule, fileModule: a.fileModule, sysModule: a.sysModule }); } },
  { name: 'capture_stop', description: 'Remove the persistent hook set for this target. DRAINS FIRST: capture_stop resets the agent ring, so stopping without draining would silently destroy everything the target produced since the last tick - the reply therefore carries drained (records pulled out and stored), drainedOk (false = the session has no drain loop, so whatever was still in the ring is gone) and dropped (the ring had already dropped records), and complete is false when either is bad. An empty result is not "nothing happened": check drained before concluding that.', inputSchema: { type: 'object', properties: { session: S } }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return setCapture(sid, false); } },
  { name: 'file_probe', description: 'Recon which loaded module’s GOT holds open/openat/read/write/close pointers (tells you what to pass as capture_start fileModule; the agent never guesses a module)', inputSchema: { type: 'object', properties: { session: S } }, handler: (a) => agentCmd(a.session, 'file_probe', {}, 20_000) },
  { name: 'object_inspect', description: 'Read a live Java object’s fields via reflection (static field path)', inputSchema: { type: 'object', properties: { session: S, className: S, field: S }, required: ['className', 'field'] }, handler: (a) => agentCmd(a.session, 'object_inspect', { className: a.className, field: a.field }) },
  { name: 'dex_search', description: 'Search a dex (b64|sha) for strings/classes/methods', inputSchema: { type: 'object', properties: { b64: S, sha: S, query: S, kinds: { type: 'array', items: S } }, required: ['query'] }, handler: async (a) => searchDex(parseDex(await dumpBuf(a)), a.query, a.kinds) },
  { name: 'dex_index', description: 'Build or reuse the persistent SQLite index for a dex (b64|known dump sha)', inputSchema: { type: 'object', properties: { b64: S, sha: S } }, handler: async (a) => ensureDexIndex(await dumpBuf(a)) },
  { name: 'dex_index_search', description: 'Search an indexed dex for strings, string callers, classes, fields, methods and reflection targets', inputSchema: { type: 'object', properties: { sha: S, query: S, limit: N }, required: ['sha', 'query'] }, handler: async (a) => searchDexIndex(String(a.sha), String(a.query), a.limit) },
  { name: 'dex_reflections', description: 'List statically resolved Class.forName targets and their callers from an indexed dex', inputSchema: { type: 'object', properties: { sha: S, limit: N }, required: ['sha'] }, handler: async (a) => ({ sha: a.sha, reflections: listDexReflections(String(a.sha), a.limit) }) },
  { name: 'dex_xref', description: 'Find callers of a method in a dex (b64|sha)', inputSchema: { type: 'object', properties: { b64: S, sha: S, method: S }, required: ['method'] }, handler: async (a) => { const buf = await dumpBuf(a); const { xref } = invokeXref(buf, parseDex(buf)); const q = String(a.method).toLowerCase(); const out: Record<string, string[]> = {}; for (const [c, cs] of xref) if (c.toLowerCase().includes(q)) out[c] = cs.slice(0, 200); return out; } },
  { name: 'dex_crypto_scan', description: 'Static crypto scan of a dex (API refs + algorithm strings)', inputSchema: { type: 'object', properties: { b64: S, sha: S } }, handler: async (a) => cryptoScan(parseDex(await dumpBuf(a))) },
  { name: 'native_disasm', description: 'Disassemble an ELF .so (b64|sha) by symbol', inputSchema: { type: 'object', properties: { b64: S, sha: S, symbol: S }, required: ['symbol'] }, handler: async (a) => { const t = join(tmpdir(), `mcp_${Date.now()}.so`); writeFileSync(t, await dumpBuf(a)); try { return await disasmSo(t, { symbol: a.symbol }); } finally { try { unlinkSync(t); } catch {} } } },
  { name: 'native_analyze', description: 'Exports/imports/NEEDED/strings of an ELF .so (b64|sha)', inputSchema: { type: 'object', properties: { b64: S, sha: S } }, handler: async (a) => { const t = join(tmpdir(), `mcp_${Date.now()}.so`); writeFileSync(t, await dumpBuf(a)); try { return await analyzeSo(t); } finally { try { unlinkSync(t); } catch {} } } },
  { name: 'native_crypto_const', description: 'Locate crypto by constant signatures in a stripped .so (b64|sha). Standard constants only — for a target that implements the algorithm itself and mutates it (rewritten IV / alphabet / polynomial), those signatures are absent by construction: use crypto_variant_scan instead', inputSchema: { type: 'object', properties: { b64: S, sha: S } }, handler: async (a) => cryptoConstScan(await dumpBuf(a)) },
  { name: 'crypto_variant_scan', description: 'Identify crypto by STRUCTURE, not by standard constants: reports each family found with a verdict of standard or variant, and for a variant the evidence (which standard part is missing, and how close the rewritten one is). Catches an app that implements MD5/base64/CRC itself and perturbs it — those match no standard signature, so native_crypto_const and the runtime API-boundary capture both go blind at once. Also states where a static scan cannot see at all (runtime-generated tables, a mutation that rewrites the anchor too)', inputSchema: { type: 'object', properties: { b64: S, sha: S } }, handler: async (a) => scanCryptoVariants(await dumpBuf(a)) },
  { name: 'native_syscall_scan', description: 'Find direct svc #0 syscalls in a .so (b64|sha) and attribute every site to a syscall number by decoding the MOV that materialises x8 before it (arm64 number table; a number that cannot be decoded statically stays unknown instead of being guessed). The same attribution backs syscall_watch, which can then hook only the sites matching a name/number filter.', inputSchema: { type: 'object', properties: { b64: S, sha: S } }, handler: async (a) => { const buf = await dumpBuf(a); const scan = svcScan(buf); const hits = scan.hits.map((h) => { const off = Number(BigInt(h.fileOff)); const at = attributeSite(buf, off); return { ...h, syscall: at.nr == null ? null : { nr: at.nr, name: syscallName(at.nr) }, attribution: at.how }; }); return { ...scan, hits, attributedCount: hits.filter((h) => h.syscall).length, unknownCount: hits.filter((h) => !h.syscall).length }; } },
  { name: 'memory_dump', description: 'Dump target memory [addr,addr+size) to a capture artifact (sha256 dedup). The reply states complete/requestedSize: a partially readable range is still kept as an artifact but marked complete:false, a range that cannot be read at all fails instead of producing an empty dump, and the size must be a positive integer within the dump cap', inputSchema: { type: 'object', properties: { session: S, addr: S, size: N }, required: ['addr', 'size'] }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); const { meta, dedup } = await dumpRegion(sid, String(a.addr).replace(/^0x/, ''), Number(a.size), 'mcp'); return { ...meta, dedup }; } },
  { name: 'flow_correlate', description: 'Join the live capture store\'s crypto stream to its TLS stream: pairs a crypto record (EVP_*/HMAC_Update) with a net record (SSL_*) that ran on the SAME THREAD inside a 200ms window - the "this plaintext was encrypted, then that request went out" question, answered from the daemon\'s own store rather than by the target. Turn capture_start on and provoke the workload (java_call) first, then call this; sinceMs / sinceCaptureId bound the window. Every reply carries caveat: this is thread+time CO-OCCURRENCE, not a content-hash proof that the payloads are the same bytes (deterministic correlation is WS-I and is not implemented), and an empty result carries reason instead of a bare empty array, with storeLoss set when the requested window reaches past evicted records.', inputSchema: { type: 'object', properties: { session: S, sinceMs: N, sinceCaptureId: N, maxPairs: N } }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return flowCorrelate(sid, { sinceMs: a.sinceMs, sinceCaptureId: a.sinceCaptureId, maxPairs: a.maxPairs }); } },
  { name: 'object_set', description: 'Write one field of a live object - the write counterpart of object_inspect (Frida-style field patching). field names the STATIC holder that carries the object (same convention as object_inspect/object_invoke), targetField is the field on that object, and value is coerced by the field declared type (boolean/int/long/float/double/String). The reply carries before/after so the effect is visible and can be put back; a final field (Kotlin val) comes back ok:false instead of pretending it worked.', inputSchema: { type: 'object', properties: { session: S, className: S, field: S, targetField: S, value: S }, required: ['session', 'className', 'field', 'targetField', 'value'] }, handler: (a) => agentCmd(a.session, 'object_set', { className: a.className ?? '', field: a.field ?? '', targetField: a.targetField ?? '', value: String(a.value ?? '') }, 20_000) },
  { name: 'jni_field_digest', description: 'Turn JNIEnv field events into "which fields did native code read or write": joins the Get/Set<Type>Field access events (field=0x..) with the GetFieldID/GetStaticFieldID events that handed those ids out, so a group reads Class#name:sig instead of an opaque pointer - the signal that shows which fields a target probes through native code. Writes that an active setValue override REWRITTEN are called out separately (group.rewritten + lastRequested vs lastValue, plus rewrittenSamples), because "the target asked for 7 and the hook stored 42" is itself the finding. Hook the field slots with jni_env_hook first (hook GetFieldID too, or ids stay unresolved), trigger the target, then call this; the drain goes through the shared drainSession path and a lossy ring is reported rather than hidden.', inputSchema: { type: 'object', properties: { session: S, sinceMs: N, limit: N, maxGroups: N } }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return jniFieldDigest(sid, { sinceMs: a.sinceMs, limit: a.limit, maxGroups: a.maxGroups }); } },
  { name: 'object_invoke', description: 'Call a no-arg method on a live object (via static field path)', inputSchema: { type: 'object', properties: { session: S, className: S, field: S, method: S }, required: ['className', 'field', 'method'] }, handler: (a) => agentCmd(a.session, 'object_invoke', { className: a.className, field: a.field, method: a.method }) },
  { name: 'dex_method_code', description: 'Extract a method’s runtime code_item bytecode from a dex (b64|sha)', inputSchema: { type: 'object', properties: { b64: S, sha: S, class: S, method: S }, required: ['class'] }, handler: async (a) => { const buf = await dumpBuf(a); return extractMethodCode(buf, parseDex(buf), String(a.class), a.method); } },
  { name: 'dex_repair', description: 'Repair a dumped dex header (file_size/checksum/signature) and store the repaired bytes as a dump artifact. Returns the header fields plus the artifact sha256/size/kind/path. The repaired dex is deliberately NOT returned inline: a packed target dex can be 100 MB+, and the caller already holds the input bytes - index or download it by the returned sha instead. dedup:true means a byte-identical artifact was already stored.', inputSchema: { type: 'object', properties: { b64: S, sha: S } }, handler: async (a) => { const buf = await dumpBuf(a); const info = repairDexHeader(buf); const { meta, dedup } = await persistArtifact(buf, { source: 'dex-repair', addr: '', tag: 'dex_repair', sessionId: '', package: '' }); return { ...info, sha256: meta.sha256, size: meta.size, kind: meta.kind, path: meta.path, dedup }; } },
  // ---- axis 1: one-glance crypto algorithm identification ----
  { name: 'crypto_identify', description: '一眼看清目标 App 用了哪些加密算法/密钥/IV — summarize all captured crypto (algorithm, key, iv, plaintext) into a plain-language report for non-experts', inputSchema: { type: 'object', properties: {} }, handler: async () => cryptoIdentify() },
  { name: 'live_captures', description: 'List the live captures streamed by the persistent hooks — crypto / net(TLS) / file / system, filterable by category (algorithm+op+preview, newest last). Each record carries func (the raw boundary that fired: EVP_CipherUpdate, SSL_write, open, ptrace, sysprop …) next to the classified algo/op, because "which function did this come from" is the question a capture answers. includeText:true adds the full printable rendering of each payload as ascii (the default preview is capped at 80 chars, which hides a marker that sits late in a buffer) so one call can answer "is this string in the traffic" without a capture_detail round trip per record', inputSchema: { type: 'object', properties: { limit: N, category: S, includeText: { type: 'boolean' } } }, handler: async (a) => { const cat = a.category ? String(a.category) : ''; const list = cat ? captures.filter(c => c.category === cat) : captures; const withText = a.includeText === true; return { total: list.length, on: captureTimers.size > 0, captures: list.slice(-(Number(a.limit) || 50)).map(c => ({ id: c.id, source: c.source, func: c.func, category: c.category, algo: c.algo, op: c.op, inl: c.inl, tid: c.tid, ts: c.ts, tsNs: c.tsNs, preview: c.preview, ...(withText ? { ascii: asciiOf(c.hex).slice(0, 4096) } : {}) })) }; } },
  { name: 'capture_detail', description: 'Full detail of one capture by id: algorithm, key(hex), iv(hex), plaintext(utf8+hex), ciphertext(hex)', inputSchema: { type: 'object', properties: { id: N }, required: ['id'] }, handler: async (a) => { const c = captures.find(x => x.id === Number(a.id)); if (!c) throw new Error('not found'); const text = Buffer.from(c.hex, 'hex').toString('utf8'); return { ...c, text }; } },
  // ---- axis 2: one-click unpack (no AOSP flashing needed) ----
  { name: 'dex_coverage', description: '方法恢复率报告 — per-method state (native/abstract/present/extracted) + recovery rate over a dumped dex', inputSchema: { type: 'object', properties: { b64: S, sha: S }, required: [] }, handler: async (a) => { const buf = await dumpBuf(a); return analyzeCoverage(buf, parseDex(buf)); } },
  { name: 'dump_all_dex', description: '一键 dump 当前目标进程所有已加载 DEX：ART DexFile 枚举 + 逐个 dump + SHA-256 去重', inputSchema: { type: 'object', properties: { session: S } }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return dumpAllDex(sid); } },
  { name: 'dex_recover', description: 'Recover extracted CodeItems from a restored snapshot into a base dex + rebuild (baseSha/baseB64 + restoredSha/restoredB64)', inputSchema: { type: 'object', properties: { baseB64: S, baseSha: S, restoredB64: S, restoredSha: S } }, handler: async (a) => { const base = await dumpBuf({ b64: a.baseB64, sha: a.baseSha }); const restored = await dumpBuf({ b64: a.restoredB64, sha: a.restoredSha }); const pd = parseDex(base); const { captures: caps, report } = recoverFromSnapshots(base, restored, pd); const rb = rebuildStandardDex(base, caps); const outSha = createHash('sha256').update(rb.dex).digest('hex'); const path = join(CAPTURES, `${outSha.slice(0, 16)}.dex`); if (!existsSync(path)) writeFileSync(path, rb.dex); const meta: DumpMeta = { sha256: outSha, size: rb.dex.length, source: 'dex-recover', addr: '0', tag: 'recovered', sessionId: '', package: '', capturedAt: Date.now(), path, kind: 'dex' }; dumps.set(outSha, meta); return { ...report, injected: rb.injected, sha256: outSha }; } },
  // ---- axis 3: everything the AI needs to drive a reversing session ----
  { name: 'trigger', description: 'Actively load a class (level 1) and invoke a safe static no-arg method (level 3) to force code paths — a trigger source for unpacking', inputSchema: { type: 'object', properties: { session: S, class: S, method: S, level: N }, required: ['class'] }, handler: (a) => agentCmd(a.session, 'trigger', { className: a.class, method: a.method ?? '', level: Number(a.level ?? 1) }, 20_000) },
  { name: 'qbdi_trace', description: 'QBDI instruction-level dynamic trace of a native function (per-instruction disassembly + return value), invoked with up to 8 unsigned integer/pointer args. symLib is REQUIRED: the agent knows no fixture module names, so name the module that defines the symbol (e.g. libc.so).', inputSchema: { type: 'object', properties: { session: S, symLib: S, symbol: S, args: { type: 'array' } }, required: ['session', 'symLib', 'symbol'] }, handler: (a) => agentCmd(a.session, 'qbdi_trace', { symLib: a.symLib, symbol: a.symbol, args: (a.args ?? []).map((v: any) => String(v)).join(',') }, 30_000) },
  { name: 'agent_ping', description: 'Liveness and latency check for one session: sends the cheapest command the agent has and reports the measured round trip in ms. Use it to tell "the target is gone" from "this command is just slow", before and after a crash-prone operation, or when a session looks hung. It fails fast (5s) instead of sitting on a normal command timeout.', inputSchema: { type: 'object', properties: { session: S }, required: ['session'] }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return agentPing(sid); } },
  { name: 'engine_selftest', description: 'Prove the native hook engine works in THIS target: the agent replaces a GOT slot in its own module, triggers a controlled call, restores it, and reports replaced / hits / fired plus the slot page permissions before and after. ok is the VERDICT (the hook fired AND the RELRO page protection was restored); commandOk only says the agent answered. A build that left the page writable comes back ok:false with a note that it is detectable, so run this before trusting hook results.', inputSchema: { type: 'object', properties: { session: S }, required: ['session'] }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return hookEngineSelftest(sid); } },
  { name: 'protocol_selftest', description: 'Command-channel integrity check: send one oversized frame whose tail marker sits past the old 8192-byte single-line cap and verify the tail survived and the whole frame arrived. Use it when replies look truncated or a session looks half-dead; kb is clamped to 1..4096. ok:false here means the channel (adb reverse / framing) is at fault, not the target.', inputSchema: { type: 'object', properties: { session: S, kb: N }, required: ['session'] }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return protocolSelfTest(sid, a.kb); } },
  { name: 'fs_list', description: 'List a directory on the DEVICE through the target process, so it sees the sandbox the way the app does (its private /data/data/... dir, /data/local/tmp, /proc/self/...). Returns name/type/size/mode/mtime per entry plus count and truncated. Start here to find shared_prefs, databases, keystores or dropped scripts, then pull one with fs_read.', inputSchema: { type: 'object', properties: { session: S, path: S }, required: ['session', 'path'] }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return listDeviceDir(sid, String(a.path ?? '')); } },
  { name: 'fs_read', description: 'Read one device file through the target process. The agent caps a read at 1MB and reports truncated honestly. Returns size, byte count, a binary flag (NUL byte present), a printable preview and the line count, plus the whole text when the file is text and is at most 256KB. Binary or oversized files come back with textOmitted saying why; pass includeBase64:true for the raw bytes.', inputSchema: { type: 'object', properties: { session: S, path: S, includeBase64: { type: 'boolean' }, includeText: { type: 'boolean' }, previewBytes: N }, required: ['session', 'path'] }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return readDeviceFile(sid, String(a.path ?? ''), { includeBase64: a.includeBase64 === true, includeText: a.includeText !== false, previewBytes: a.previewBytes }); } },
  { name: 'load_library', description: '把任意 .so 加载进目标进程（如 frida-gadget，随后 gadget 会按 script 模式自动跑你的 frida 脚本）。可选 symbol 探测。dlopen from inside the target.', inputSchema: { type: 'object', properties: { session: S, path: S, symbol: S }, required: ['path'] }, handler: (a) => agentCmd(a.session, 'load_so', { path: a.path, symbol: a.symbol ?? '' }, 30_000) },
];

export const MCP_MAP = new Map(MCP_TOOLS.map(t => [t.name, t]));

export async function handleMcp(reqBody: string, res: ServerResponse, opts?: { package?: string }) {
  let msg: any;
  try { msg = JSON.parse(reqBody); } catch { res.writeHead(400).end('bad json'); return; }
  const pin = opts?.package;
  const reply = (result?: unknown, error?: unknown) => {
    const body = JSON.stringify({ jsonrpc: '2.0', id: msg.id, ...(error ? { error } : { result }) });
    res.writeHead(200, { 'content-type': 'application/json' }); res.end(body);
  };
  if (msg.method === 'initialize') return reply({ protocolVersion: '2024-11-05', capabilities: { tools: {} }, serverInfo: { name: 'adhd', version: '0.1.0' } });
  if (msg.method === 'notifications/initialized' || msg.method === 'notifications/cancelled') { res.writeHead(202).end(); return; }
  if (msg.method === 'ping') return reply({});
  if (msg.method === 'tools/list') return reply({ tools: MCP_TOOLS.map(t => ({ name: t.name, description: t.description, inputSchema: t.inputSchema })) });
  if (msg.method === 'tools/call') {
    const name = msg.params?.name;
    const t = MCP_MAP.get(name);
    if (!t) return reply(undefined, { code: -32602, message: `unknown tool: ${name}` });
    let args = { ...(msg.params?.arguments ?? {}) };
    if (pin && name === 'process_list') {
      const out = [...sessions.values()].filter(s => s.package === pin);
      return reply({ content: [{ type: 'text', text: JSON.stringify(out, null, 2) }] });
    }
    if (pin && args.session == null) {
      const sid = sessionForPackage(pin);
      if (sid) args.session = sid;
    }
    try {
      const out = await t.handler(args);
      if (t.raw) return reply(out);
      return reply({ content: [{ type: 'text', text: JSON.stringify(out, null, 2) }] });
    } catch (e) { return reply({ content: [{ type: 'text', text: 'error: ' + (e as Error).message }], isError: true }); }
  }
  return reply(undefined, { code: -32601, message: `method not found: ${msg.method}` });
}
